import os, sys, ast, inspect, importlib, subprocess

ROOT = os.getcwd()
SKIP_DIRS = {'.git', '__pycache__', '.tox', 'build', '.eggs', '.mypy_cache', 'node_modules'}

E1 = "pytest cvxpy/tests/test_conic_solvers.py -k copt_exp_soc_1 -> StandardTestMixedCPs.test_exp_soc_1(solver='COPT') with no tolerance kwargs (default tolerances)"
E2 = "check_gradient(x=None, epsilon=1e-8) on an NLP derivative test, x defaulting to self.x0 with a large objective value (logistic case)"
E3 = "eval_hessian_vals_coo_lower_tri called after a previous forward pass at a different point (no objective_forward(x)/constraint_forward(x) pinning)"


def P(name, fn):
    try:
        val = fn()
    except BaseException as e:
        val = "__error__: " + type(e).__name__ + ": " + str(e)
    try:
        probe(name, val)
    except BaseException:
        pass


def read_text(path):
    with open(path, 'r', encoding='utf-8', errors='replace') as fh:
        return fh.read()


def iter_py_files():
    for root, dirs, files in os.walk(ROOT):
        dirs[:] = [d for d in dirs if d not in SKIP_DIRS]
        for f in files:
            if f.endswith('.py'):
                yield os.path.join(root, f)


def rel(p):
    try:
        return os.path.relpath(p, ROOT)
    except BaseException:
        return p


def find_files(needle):
    hits = []
    for p in iter_py_files():
        try:
            t = read_text(p)
        except BaseException:
            continue
        if needle in t:
            hits.append(rel(p))
    return sorted(hits)


def find_named_files(sub):
    out = []
    for root, dirs, files in os.walk(ROOT):
        dirs[:] = [d for d in dirs if d not in SKIP_DIRS]
        for f in files:
            if f.endswith('.py') and sub in f.lower():
                out.append(rel(os.path.join(root, f)))
    return sorted(out)


def extract_defs(path, name, maxlen=5000):
    try:
        full = path if os.path.isabs(path) else os.path.join(ROOT, path)
        src = read_text(full)
        tree = ast.parse(src)
        lines = src.splitlines()
    except BaseException as e:
        return "__error__: " + type(e).__name__ + ": " + str(e)
    out = []
    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) and node.name == name:
            start = node.lineno - 1
            end = getattr(node, 'end_lineno', start + 1)
            seg = "\n".join(lines[start:end])
            out.append({"lineno": node.lineno, "source": seg[:maxlen]})
    return out


def defs_containing(path, needle, maxlen=6000):
    try:
        full = path if os.path.isabs(path) else os.path.join(ROOT, path)
        src = read_text(full)
        tree = ast.parse(src)
        lines = src.splitlines()
    except BaseException as e:
        return "__error__: " + type(e).__name__ + ": " + str(e)
    out = []
    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            start = node.lineno - 1
            end = getattr(node, 'end_lineno', start + 1)
            seg = "\n".join(lines[start:end])
            if needle in seg:
                out.append({"name": node.name, "lineno": node.lineno, "source": seg[:maxlen]})
    return out


def grep_lines(path, needles, maxlines=60):
    try:
        full = path if os.path.isabs(path) else os.path.join(ROOT, path)
        out = []
        for i, line in enumerate(read_text(full).splitlines(), 1):
            if any(nd in line for nd in needles):
                out.append("%d: %s" % (i, line.strip()))
                if len(out) >= maxlines:
                    break
        return out
    except BaseException as e:
        return "__error__: " + type(e).__name__ + ": " + str(e)


def module_name_for(relpath):
    r = relpath
    if r.endswith('.py'):
        r = r[:-3]
    parts = r.replace('\\', '/').split('/')
    if parts and parts[-1] == '__init__':
        parts = parts[:-1]
    return '.'.join([p for p in parts if p not in ('', '.')])


def sig_info(path, fname):
    try:
        modname = module_name_for(path)
        mod = sys.modules.get(modname)
        if mod is None:
            mod = importlib.import_module(modname)
        fn = getattr(mod, fname, None)
        owner = modname
        if fn is None:
            for an, av in vars(mod).items():
                if inspect.isclass(av) and hasattr(av, fname):
                    fn = getattr(av, fname)
                    owner = modname + '.' + an
                    break
        if fn is None:
            return {"module": modname, "found": False}
        sig = inspect.signature(fn)
        defaults = {}
        for k, v in sig.parameters.items():
            if v.default is not inspect.Parameter.empty:
                defaults[k] = repr(v.default)
        return {"module": modname, "owner": owner, "found": True,
                "signature": str(sig), "defaults": defaults}
    except BaseException as e:
        return "__error__: " + type(e).__name__ + ": " + str(e)


def def_name_usage(path, fname):
    try:
        full = path if os.path.isabs(path) else os.path.join(ROOT, path)
        src = read_text(full)
        tree = ast.parse(src)
    except BaseException as e:
        return "__error__: " + type(e).__name__ + ": " + str(e)
    res = {}
    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) and node.name == fname:
            used = set()
            for n in ast.walk(node):
                if isinstance(n, ast.Attribute):
                    used.add(n.attr)
                elif isinstance(n, ast.Name):
                    used.add(n.id)
            res[fname] = {
                "uses_objective_forward": 'objective_forward' in used,
                "uses_constraint_forward": 'constraint_forward' in used,
                "mentions_epsilon": 'epsilon' in used,
            }
    return res


def run_pytest(args, timeout=600):
    cmd = [sys.executable, '-m', 'pytest', '-q', '--no-header', '-p', 'no:cacheprovider'] + list(args)
    try:
        r = subprocess.run(cmd, cwd=ROOT, stdout=subprocess.PIPE,
                           stderr=subprocess.STDOUT, timeout=timeout)
        out = r.stdout.decode('utf-8', 'replace')
        return {"returncode": r.returncode, "tail": out[-7000:]}
    except subprocess.TimeoutExpired as e:
        raw = e.stdout or b''
        if isinstance(raw, str):
            raw = raw.encode('utf-8', 'replace')
        return {"returncode": "__timeout__", "tail": raw.decode('utf-8', 'replace')[-7000:]}
    except BaseException as e:
        return "__error__: " + type(e).__name__ + ": " + str(e)


# ---------------- Example 1: COPT exp_soc test ----------------
P(E1, lambda: run_pytest(["cvxpy/tests/test_conic_solvers.py", "-k", "copt_exp_soc_1"], timeout=600))


