    try:
        import coptpy  # noqa
        return {"importable": True, "file": getattr(coptpy, '__file__', None)}
    except BaseException as e:
        return {"importable": False, "error": type(e).__name__ + ": " + str(e)}


P(E1 + " :: coptpy", _coptpy)
P(E1 + " :: test file exists", lambda: os.path.exists(os.path.join(ROOT, "cvxpy/tests/test_conic_solvers.py")))
P(E1 + " :: files mentioning copt_exp_soc_1", lambda: find_files("copt_exp_soc_1"))
P(E1 + " :: files defining test_exp_soc_1", lambda: find_files("def test_exp_soc_1"))
P(E1 + " :: enclosing defs of copt_exp_soc_1", lambda: defs_containing("cvxpy/tests/test_conic_solvers.py", "copt_exp_soc_1"))
P(E1 + " :: test_exp_soc_1 def source", lambda: [extract_defs(p, "test_exp_soc_1") for p in find_files("def test_exp_soc_1")])
P(E1 + " :: copt files", lambda: find_named_files("copt"))
P(E1 + " :: copt tolerance/bound lines", lambda: {p: grep_lines(p, ["FeasTol", "DualTol", "bound", "1e-9", "infinity"]) for p in find_named_files("copt")})

# ---------------- Example 2: check_gradient ----------------
P(E2 + " :: files defining check_gradient", lambda: find_files("def check_gradient"))
P(E2 + " :: files mentioning check_gradient", lambda: find_files("check_gradient"))
P(E2 + " :: definitions source", lambda: {p: extract_defs(p, "check_gradient") for p in find_files("def check_gradient")})
P(E2 + " :: signatures/defaults", lambda: {p: sig_info(p, "check_gradient") for p in find_files("def check_gradient")})
P(E2 + " :: forward-pinning usage", lambda: {p: def_name_usage(p, "check_gradient") for p in find_files("def check_gradient")})


