import numpy as np
import cvxpy as cp

NAME1 = "AtomTestConfig('sigma_max_nonsquare', lambda x: cp.sigma_max(x), [(2, 3)], 'unrestricted') -> cp.sigma_max(x) with x shape (2,3)"
NAME2 = "AtomTestConfig('sigma_max_tall', lambda x: cp.sigma_max(x), [(4, 2)], 'unrestricted') -> cp.sigma_max(x) with x shape (4,2)"

EXAMPLES = [(NAME1, (2, 3)), (NAME2, (4, 2))]


def to_arr(v):
    try:
        import scipy.sparse as sp
        if sp.issparse(v):
            return np.asarray(v.todense(), dtype=float)
    except Exception:
        pass
    try:
        return np.asarray(v, dtype=float)
    except Exception:
        return np.array(v, dtype=object)


def numerical_grad(shape, seed=0, eps=1e-6):
    rng = np.random.default_rng(seed)
    X = rng.standard_normal(shape)

    def f(M):
        return np.linalg.svd(M, compute_uv=False)[0]

    G = np.zeros(shape, dtype=float)
    it = np.nditer(X, flags=['multi_index'])
    while not it.finished:
        idx = it.multi_index
        Xp = X.copy()
        Xp[idx] += eps
        Xm = X.copy()
        Xm[idx] -= eps
        G[idx] = (f(Xp) - f(Xm)) / (2.0 * eps)
        it.iternext()
    return X, G


def get_grad(expr, x, shape):
    try:
        g = expr.grad
    except AttributeError:
        if hasattr(cp, 'grad'):
            g = cp.grad(expr)
        else:
            raise

    if callable(g) and not isinstance(g, (dict, np.ndarray)):
        try:
            g = g()
        except TypeError:
            try:
                g = g(x)
            except TypeError:
                pass

    if isinstance(g, dict):
        try:
            if x in g:
                return to_arr(g[x])
        except Exception:
            pass
        vals = list(g.values())
        if len(vals) == 1:
            return to_arr(vals[0])
        for k, v in g.items():
            if tuple(getattr(k, 'shape', ())) == tuple(shape):
                return to_arr(v)
        raise RuntimeError(
            "unrecognized grad keys: " + repr([type(k).__name__ for k in g.keys()]))

    if isinstance(g, (list, tuple)):
        for item in g:
            if isinstance(item, tuple) and len(item) == 2 and item[0] is x:
                return to_arr(item[1])
        if len(g) == 1:
            return to_arr(g[0])

    try:
        return to_arr(g[x])
    except Exception:
        pass
    return to_arr(g)


def analytical_grad(shape, seed=0):
    rng = np.random.default_rng(seed)
    X = rng.standard_normal(shape)
    x = cp.Variable(shape)
    expr = cp.sigma_max(x)
    x.value = X
    try:
        _ = expr.value
    except Exception:
        pass
    return get_grad(expr, x, shape)


for name, shape in EXAMPLES:
    try:
        g = analytical_grad(shape)
        probe(name, g.tolist())
    except Exception as e:
        probe(name, "__error__: " + type(e).__name__ + ": " + str(e))

    try:
        _, gn = numerical_grad(shape)
        probe(name + " [numerical gradient]", gn.tolist())
    except Exception as e:
        probe(name + " [numerical gradient]",
              "__error__: " + type(e).__name__ + ": " + str(e))

    try:
        g = analytical_grad(shape)
        _, gn = numerical_grad(shape)
        probe(name + " [max abs diff]",
              float(np.max(np.abs(np.asarray(g, dtype=float) - gn))))
    except Exception as e:
        probe(name + " [max abs diff]",
              "__error__: " + type(e).__name__ + ": " + str(e))

