    try:
        g = analytical_grad(shape)
        probe(name, g.tolist())
    except Exception as e:
        probe(name, "__error__: " + type(e).__name__ + ": " + str(e))

    try:
        _, gn = numerical_grad(shape)
        probe(name + " [numerical gradient]", gn.tolist())
    except Exception as e:
        probe(name + " [numerical gradient]",
              "__error__: " + type(e).__name__ + ": " + str(e))

    try:
        g = analytical_grad(shape)
        _, gn = numerical_grad(shape)
        probe(name + " [max abs diff]",
              float(np.max(np.abs(np.asarray(g, dtype=float) - gn))))
    except Exception as e:
        probe(name + " [max abs diff]",
